{
    // 📝 Replace with your own phone number in E.164 format
    // E.164 format: +[country code][number], e.g. +237 is Cameroon
    "phone_number": "+237670000001"
}

{
    // The {{token}} variable was saved automatically by step 1.1
    "token": "{{token}}"
}

{
    // 📝 Replace these fields with realistic test data
    // In sandbox mode, any valid-looking data is accepted
    "first_name": "Jane",
    "last_name": "Doe",
    "email": "jane.doe.tutorial@example.com",
    "phone_number": "+237670000001",
    "address": {
        "street": "45 Rue de la Paix",
        "town": "Douala",
        "postcode": "00237",
        // ISO 3166-1 alpha-3 country code (CMR = Cameroon)
        "country": "CMR"
    }
}

{
    // applicantId is filled automatically from the environment variable saved in step 2.1
    "applicant_id": "{{applicantId}}",

    // Supported types: passport | national_identity_card | driving_licence
    "type": "passport",

    "filename": "passport_sample.jpg",

    // In a real integration this is a base64-encoded image.
    // For sandbox testing, Entrust accepts a small placeholder string.
    "data": "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg=="
}

{
    // applicantId saved from step 2.1
    "applicant_id": "{{applicantId}}",

    // workflow_id is configured in your .env as KYC_DEFAULT_WORKFLOW_ID
    // Leave blank to use the default workflow, or provide a specific one
    "workflow_id": "{{kyc_workflow_id}}"
}

request.description:
Checks your current KYC verification level and the resulting transaction limits.

**Response breakdown:**
- `current_kyc_level`: `none` | `basic` | `full`
- `transaction_limits.dailyLimit`: Maximum XAF you can transact per day
- `latest_verification.verification_status`: `pending` | `approved` | `rejected`

**Expected response when approved:**
```json
{
  "data": {
    "current_kyc_level": "basic",
    "transaction_limits": { "dailyLimit": 100000 }
  }
}
```

⚠️  **If status is still `none`:** Re-run this request after a few seconds (sandbox processing is fast).

