{
    // Amount in XAF (Central African Franc)
    // Must be between 100 and 1,000,000 XAF for Basic KYC
    "amount": 500.00,

    // The mobile money number to pull funds FROM
    "phoneNumber": "+237670000001",

    // Mobile money provider: "mtn" | "orange" | "airtel"
    "provider": "mtn",

    // Your Stellar wallet address (saved automatically from step 1.3)
    // Funds are credited here on the Stellar network
    "stellarAddress": "{{stellarAddress}}",

    // Your user ID (saved automatically from step 1.1 / 1.3)
    "userId": "{{userId}}",

    // Optional: a human-readable note attached to the transaction
    "notes": "Tutorial deposit — Step 3"
}

{
    // Amount to withdraw in XAF — must be less than or equal to deposited balance
    // Keep this ≤ the amount deposited in step 3.1 (500 XAF in the tutorial)
    "amount": 200.00,

    // The mobile money number to send funds TO
    "phoneNumber": "+237670000001",

    // Mobile money provider for the destination number
    "provider": "mtn",

    // Your Stellar wallet address — funds are debited from here
    "stellarAddress": "{{stellarAddress}}",

    // Your user ID
    "userId": "{{userId}}",

    // Optional note
    "notes": "Tutorial withdrawal — Step 4"
}
